-- New classes and cards from the "Card Design" doc: AP costs, ultimate
-- charge, priority, elements and statuses on attacks, monster cards, the
-- Black Mage / Master Craftsman / Necromancer classes, and a general card
-- set in every class's starter deck. No schema change -- all of it is new
-- jsonb props (see src/model/cardTypes.ts) and new rows.
--
-- Generated by `npm run catalog:sql` from src/model/catalogData.ts; upserts
-- only, so it also re-applies the existing classes and cards with their AP
-- costs. cards.image_url is left alone (run `npm run cards:art -- --upload`
-- for the new artwork).
--
-- A new card category ("monster") needs a matching client: older builds
-- skip cards they don't recognize, so they keep working with the rest.

on conflict (id) do update set
  name = excluded.name,
  description = excluded.description,
  counts_category = excluded.counts_category,
  tiers = excluded.tiers;

on conflict (id) do update set
  name = excluded.name,
  base_stats = excluded.base_stats,
  ultimate = excluded.ultimate,
  passives = excluded.passives,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  props = excluded.props;

on conflict (class_id, synergy_id) do nothing;

on conflict (class_id, card_id) do update set
  copies = excluded.copies;
